    data['stateful'] = stateful
    data['pure'] = pure
    data['idempotent'] = idempotent
    data['allowProbe'] = allow_probe
    if catalogs is not UNSET:
        data['catalogs'] = catalogs
    data['portGroups'] = port_groups
    data['args'] = args
    data['returns'] = returns
    data['kind'] = kind
    data['isTestFor'] = is_test_for
    data['isDev'] = is_dev
